import{z as o,x as l,o as A,c as p,q as r,j as n,D as i,d as e,s,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"硬掩模 SiN / TiN","description":"","frontmatter":{"title":"硬掩模 SiN / TiN","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hardmask-sin-tin.md","filePath":"litho/hardmask-sin-tin.md","lastUpdated":1791413859000}'),d={name:"litho/hardmask-sin-tin.md"};function D(h,E,C,N,m,S){const t=l("Mermaid");return A(),p("div",null,[E[2]||(E[2]=r('<h1 id="硬掩模-sin-tin" tabindex="-1">硬掩模 SiN / TiN <a class="header-anchor" href="#硬掩模-sin-tin" aria-label="Permalink to &quot;硬掩模 SiN / TiN&quot;">​</a></h1><div class="epigraph"><p>薄胶只负责定义边；纵向深度交给更耐打的膜。SiN 与 TiN 一类硬掩模把成像预算和深度预算拆开。</p><footer>—— 对照多层抗蚀剂 / 硬掩模转印的产线通称；[三层 SOC](/litho/trilayer-soc-sog) 已写有机硬掩模栈</footer></div><p><a href="/litho/ler-transfer-smoothing">上一课</a>把边频谱的转印写完。缺口是材料栈：EUV 薄胶和浸没薄胶都不够直接啃厚介质或硅。<a href="/litho/trilayer-soc-sog">三层胶</a> 与 <a href="/litho/rie-pattern-transfer">RIE</a> 已引入硬掩模角色；本课钉 SiN、TiN 在集成里的位置——无机掩模如何改选择比、形貌和计量。各向异性与侧壁钝化，留给<a href="/litho/anisotropy-passivation">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SiN（或 SiO<sub>x</sub>N<sub>y</sub>）常用作接触/浅槽的介电硬掩模；TiN 出现在金属硬掩模（MHM）与某些栅/BEOL 栈。胶先转到硬掩模，再以硬掩模为掩去刻目标。选择比窗口从「胶对目标」变成两段：「胶对硬掩模」×「硬掩模对目标」。每段可单独优化气体，代价是多一步、新缺陷（硬掩模残、金属沾污）和新的 CD 偏置。</p><p><span class="marginnote">术语翻译：选择比就是「刻谁快、刻谁慢」的比例——10:1 表示目标每被刻掉 10 nm，掩模只损失 1 nm。</span></p><p><span class="marginnote">数字实例：50 nm 薄胶直接刻硅，选择比 2:1 只能啃 100 nm 深；中间插一层 50 nm SiN，第二跳对硅 10:1，就能刻穿 500 nm 的目标层。两段相乘，深度预算就这么被翻上去了。</span></p><p>缺口是<strong>为何是这两种膜、以及偏置如何进 OPC</strong>，不是重讲三层涂覆顺序。TiN 不透明或高反射，影响对准与 overlay 标记衬度；SiN 应力影响翘曲（后课晶圆形变）。OPC 核必须声明是对着哪一跳 AEI。</p><h3 id="金属硬掩模的计量陷阱" tabindex="-1">金属硬掩模的计量陷阱 <a class="header-anchor" href="#金属硬掩模的计量陷阱" aria-label="Permalink to &quot;金属硬掩模的计量陷阱&quot;">​</a></h3><p>TiN AEI 的 SEM 衬度、充电与真实硅 AEI 不同。把 MHM CD 当最终电学 CD，会把后续金属填充偏置漏掉。签核轮廓要写「MHM AEI」还是「最终槽」。</p><p><span class="marginnote">硬掩模厚度是 AR 与选择比的旋钮：太薄打穿，太厚开口 AR 升、胶更难转印。厚度均匀性变成全场 CDU 项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈设计：胶 / SiARC 或 SOC / SiN 或 TiN / 目标。每跳食谱独立，成对计量独立校准核。与 BARC open 课衔接：开硬掩模的那一跳往往是 CD 敏感步。TiN 要用无残或可控残的剥离，避免金属污染前道。应力与后续对准：标记设计课已有传感器；本课要求硬掩模开窗策略不毁掉标记。</p><p>OPC 核的 AEI 目标必须写明跳数。混用「开 TiN 后」和「最终槽」两套 SEM，密度斜率会拧反。Levinson 把 ADI/AEI 当合同；硬掩模只是把 AEI 拆成两张合同。</p>',14)),(A(),n(B,null,{default:i(()=>[s(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20J1%5B%22%E8%B7%B3%E4%B8%80%EF%BC%9A%E8%96%84%E8%83%B6%20%E2%86%92%20%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%20--%3E%20P1%5B%22%E4%BD%8E%20AR%E3%80%81%E9%80%89%E6%8B%A9%E6%AF%94%E9%80%82%E4%B8%AD%E3%80%81CD%20%E6%95%8F%E6%84%9F%E6%AD%A5%22%5D%0A%20%20J2%5B%22%E8%B7%B3%E4%BA%8C%EF%BC%9A%E7%A1%AC%E6%8E%A9%E6%A8%A1%20%E2%86%92%20%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20P2%5B%22%E9%AB%98%20AR%E3%80%81%E9%AB%98%E9%80%89%E6%8B%A9%E6%AF%94%E3%80%81%E5%BC%BA%E9%92%9D%E5%8C%96%22%5D%0A%20%20FILM%7B%22%E7%A1%AC%E6%8E%A9%E6%A8%A1%E9%80%89%E6%9D%90%22%7D%20--%20%22%E4%BB%8B%E7%94%B5%E7%9B%AE%E6%A0%87%EF%BC%9A%E6%8E%A5%E8%A7%A6%20%2F%20%E6%B5%85%E6%A7%BD%22%20--%3E%20SIN%5B%22SiN%EF%BC%9A%E4%BB%8B%E7%94%B5%EF%BC%8C%E6%B3%A8%E6%84%8F%E5%BA%94%E5%8A%9B%E7%BF%98%E6%9B%B2%22%5D%0A%20%20FILM%20--%20%22%E9%87%91%E5%B1%9E%20%2F%20BEOL%20%E6%A0%88%22%20--%3E%20TIN%5B%22TiN%EF%BC%9A%E4%B8%8D%E9%80%8F%E6%98%8E%E9%AB%98%E5%8F%8D%E5%B0%84%EF%BC%8C%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%E5%89%AF%E4%BA%A7%E7%89%A9%22%5D%0A%20%20P1%20--%3E%20SUM%5B%22CD%20%E5%81%8F%E7%BD%AE%20%3D%20%E4%B8%A4%E8%B7%B3%E4%B9%8B%E5%92%8C%EF%BC%8C%E5%AF%86%E5%BA%A6%E6%A0%B8%E5%88%86%E5%B1%82%22%5D%0A%20%20P2%20--%3E%20SUM%0A%20%20SIN%20--%3E%20SUM%0A%20%20TIN%20--%3E%20SUM%0A"})]),fallback:i(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"硬掩模把「成像用薄胶」和「刻穿用厚掩」解耦。第一跳：低 AR、对胶选择比适中。第二跳：高 AR、对硬掩模高选择比、强钝化。CD 偏置是两跳之和，密度核可能要分层。TiN 还可能在等离子体中产金属副产物，改变放电——食谱窗口比 SiN 更脏，颗粒与缺陷检测要跟上。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者以为硬掩模只是「更耐刻的胶」，成像精度不受影响。实际上每一跳都有自己的 CD 偏置与密度效应，级联偏置必须分账；把「开 TiN 后」的 SEM 当「最终槽」的尺寸报给 OPC，会修错跳，金属填充阶段才暴露问题。")],-1)),(A(),n(B,null,{default:i(()=>[s(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E8%96%84%E8%83%B6%E8%BE%B9%22%5D%20--%3E%20HM1%5B%22%E5%BC%80%20SiN%20%2F%20TiN%22%5D%0A%20%20HM1%20--%3E%20HM2%5B%22%E7%A1%AC%E6%8E%A9%E6%A8%A1%E5%BD%93%E6%8E%A9%E5%88%BB%E7%9B%AE%E6%A0%87%22%5D%0A%20%20HM2%20--%3E%20FIN%5B%22%E6%9C%80%E7%BB%88%E6%A7%BD%20%2F%20%E5%AD%94%22%5D%0A%20%20HM1%20--%3E%20BIAS%5B%22%E5%81%8F%E7%BD%AE%201%22%5D%0A%20%20HM2%20--%3E%20BIAS2%5B%22%E5%81%8F%E7%BD%AE%202%22%5D%0A"})]),fallback:i(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p>两跳偏置必须分账：开硬掩模的 CD 敏感步与最终槽的 AR 步不是同一个核。混报 AEI 会让 OPC 去修错的一跳。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不规定某节点必须用 TiN 或 SiN。不重写 ALD 成膜全文。金属硬掩模与后道集成的污染控制只点名，细节属缺陷课。</p><p>后课默认：深度预算在硬掩模上，胶只定义边。下一课写如何用钝化把硬掩模开口刻直。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SiN/TiN 把成像与深度拆成两跳选择比，CD 偏置是级联。</li><li>计量轮廓必须声明看到哪一跳。</li><li>应力、反射、金属残是集成税。</li><li>出处：多层硬掩模转印通称；Levinson 流程叙述；三层胶前课。</li></ul>',6))])}const f=o(d,[["render",D]]);export{u as __pageData,f as default};
